class Base {
    public:
        virtual ReturnType functionName(Parameters) const; // Declaration of a virtual function
};

class Derived : public Base {
    public:
        ReturnType functionName(Parameters) const override; // Override in derived class
};

code_example:
#include <iostream>
class Shape {
public:
    virtual void draw() const {
        std::cout << "Drawing a shape" << std::endl;
    }
    virtual ~Shape() = default; // Virtual destructor for proper cleanup
};

class Circle : public Shape {
public:
    void draw() const override {
        std::cout << "Drawing a circle" << std::endl;
    }
};

class Square : public Shape {
public:
    void draw() const override {
        std::cout << "Drawing a square" << std::endl;
    }
};

int main() {
    Shape* shape1 = new Circle();
    Shape* shape2 = new Square();
    shape1->draw(); // Calls Circle::draw() at runtime
    shape2->draw(); // Calls Square::draw() at runtime
    delete shape1;
    delete shape2;
    return 0;
}
